head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.gRdoCreatLoc_tp = "01"; // 등록구분_미사용
scwin.LastJob = "";
scwin.gDepCd = js_dep_cd;
scwin.gUIsurCd; // update시 팝업에 넘겨주기 위해  필요
scwin.gSelctBasYy; // update시 팝업에 넘겨주기 위해  필요
scwin.gExcnt;
scwin.gBelngDepCd; // 상위부서코드
scwin.gBelngDepCd = js_belngdepcd;

// 20250509

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        await scwin.init();

        // 회사정보 로딩
        $c.cm.fn_com_isur(txb_isur_cd, txb_com_abbrv);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF37409.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init = async function() {
    await scwin.setCode();

    // 달력
    const ToDay = new Date();
    const yyyy = parseInt(ToDay.getYear(), 10); // 현재년도
    const byyyy = parseInt(ToDay.getYear() - 1, 10); // 전년도
    const mm = parseInt(ToDay.getMonth(), 10) + 1;
    let str = "";
    // 선정기준년도  셋팅
    for (let i = yyyy; i >= 1998; i--) {
        str += i + "^" + i + ",";
    }
    str = str.substring(0, str.length - 1);
    cmb_YYYY.CBData = str;

    // 시상년도 셋팅
    const nyyyy = parseInt(ToDay.getYear() + 1, 10); // 다음년도

    str = "";
    for (let i = nyyyy; i >= 1998; i--) {
        str += i + "^" + i + ",";
    }
    str = str.substring(0, str.length - 1);
    cmb_AW_YYYY.CBData = str;

    // 등록구분 초기화(추후 엑셀 등록 요청시 주석 풀것)
    // setObjectValue(rdo_creatloc_tp, "01");

    txt_SelectBasYy.style.visibility = "hidden";
    params = $c.frame.path("../").params;
    str = "";
    pnl_valueup.hide(); // 밸류업팀에서 입력하는 부분
    lbl_2.hide();

    // 시장구분에 따른 유형설정
    if (js_market === "1") {
        // 유가_선정유형
        label_1.setValue("선정유형");
        str = "11^공시우수법인,12^우수위원,13^공시우수법인(코스닥)";
    } else if (js_market === "2") {
        // 코스닥_유형
        label_1.setValue("유형");
        str = "21^장기성실공시우수,22^실적예측공시우수,23^IR활동우수,24^종합평가우수,25^우수위원";
    } else {
        if (scwin.gBelngDepCd === "1I00" || scwin.gDepCd === "1I00") {
            // 밸류업지원부
            str = "99^밸류업 우수기업";
            pnl_valueup.show(""); // 밸류업팀에서 입력하는 부분
            lbl_2.show("");
        } else {
            str = "99^밸류업 우수기업,21^(코)장기성실공시우수,22^(코)실적예측공시우수,23^(코)IR활동우수,24^(코)종합평가우수,25^(코)우수위원,11^(유)공시우수법인,12^(유)우수위원,13^(유)공시우수법인(코스닥)";
        }
    }
    cmb_Excnt.CBData = str;
    if (params === "update") {
        // 수정
        btn_Save.setBackgroundImage("../img/btn_Chg.gif");

        // rdo_creatloc_tp.Enable = false;
        txb_isur_cd.setReadOnly(true);
        img_com_srch.style.visibility = "hidden";
        scwin.gUIsurCd = $c.frame.path("../").scwin.gUIsurCd;
        scwin.gSelctBasYy = $c.frame.path("../").scwin.gSelctBasYy;
        gComAbbrv = $c.frame.path("../").gComAbbrv;
        scwin.gExcnt = $c.frame.path("../").scwin.gExcnt;
        url += "&ISUR_CD=" + scwin.gUIsurCd;
        url += "&SELCT_BAS_YY=" + scwin.gSelctBasYy;
        url += "&SCREN_ID=" + "ULDSTF37409.xml";
        url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
        const sbmOptions = {
            id : "sbm_dts_List",
            action : "/ByPass.do",
            ref : "",
            target : "dts_List=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    } else {
        // 등록
        btn_Delete.style.visibility = "hidden";
        cmb_YYYY.setValue(byyyy);
        cmb_AW_YYYY.setValue(yyyy);
        if (js_market === "1") {
            cmb_Excnt.setValue("11");
        } else if (js_market === "2") {
            cmb_Excnt.setValue("21");
        }
    }
    // dts_FileList.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인
    dts_FileList.insertRow();
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF37409.btn_Close_onclick" });
    }
};

/**
 * @method
 * @name txb_isur_cd_onblur
 * @description txb_isur_cd 포커스 이탈 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_isur_cd_onblur = function() {
    try {
        if (stFocusGrid === false) {
            Grd_com_isur.style.display = "none";
        }
        if (txb_isur_cd.getValue() === "") {
            txb_com_abbrv.setValue("");
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF37409.txb_isur_cd_onblur" });
    }
};

/**
 * @method
 * @name txb_isur_cd_onfocus
 * @description txb_isur_cd 포커스 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_isur_cd_onfocus = function() {
    try {
        Grd_com_isur.style.display = "none";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF37409.txb_isur_cd_onfocus" });
    }
};

/**
 * @method
 * @name txb_isur_cd_onkeyup
 * @description txb_isur_cd 키 입력 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_isur_cd_onkeyup = function() {
    try {
        if (txb_isur_cd.getValue() === "") {
            Grd_com_isur.style.display = "none";
        } else {
            if (params !== "update") {
                if (window.event.keyCode === 40) {
                    // 아래화살표눌렀을때 그리드로 포커스
                    Grd_com_isur.focus();
                } else {
                    $c.cm.fn_com_isur_nm(window.event.keyCode);
                }
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF37409.txb_isur_cd_onkeyup" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnKeyPress
 * @description Grd com isur On Key Press 처리
 * @param {*} kcode kcode
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    try {
        if (kcode === '13') {
            $c.cm.fn_com_Confirm_set();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF37409.Grd_com_isur_OnKeyPress" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnDblClick
 * @description Grd_com_isur 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnDblClick = function(row, colid) {
    try {
        $c.cm.fn_com_Confirm_set();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF37409.Grd_com_isur_OnDblClick" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnClick
 * @description Grd_com_isur 클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnClick = function(row, colid) {
    try {
        Grd_com_isur.style.display = "";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF37409.Grd_com_isur_OnClick" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnSetFocus
 * @description Grd com isur On Set Focus 처리
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnSetFocus = function() {
    try {
        stFocusGrid = true;
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF37409.Grd_com_isur_OnSetFocus" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnKillFocus
 * @description Grd_com_isur 포커스 이탈 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnKillFocus = function() {
    try {
        stFocusGrid = false;
        Grd_com_isur.style.display = "none";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF37409.Grd_com_isur_OnKillFocus" });
    }
};

/**
 * @method
 * @name MxDataSet_com_isur_OnFilter
 * @description Mx Data Set com isur On Filter 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    try {
        if (skw !== "" && foColum === "1") {
            f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
            f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
            if (f1.indexOf(skw) !== -1 || f2.indexOf(skw) !== -1) return true;

            else return false;
        } else return true;
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF37409.MxDataSet_com_isur_OnFilter" });
    }
};

/**
 * @method
 * @name img_com_srch_onclick
 * @description img_com_srch 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_com_srch_onclick = function() {
    try {
        $c.cm.IsurcdSearch(txb_isur_cd, txb_com_abbrv);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF37409.img_com_srch_onclick" });
    }
};

/**
 * @method
 * @name btn_Save_onclick
 * @description 「저장」 클릭 이벤트
 * @returns {Promise<void>}
