        await $c.win.alert(scwin.LastJob + "에 실패하였습니다.");
        // alert(getObjectValue(txb_com_abbrv) + "은(는) " + getObjectValue(cmb_YYYY) + "년에 등록된 내역이 존재합니다.");
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF37409.trs_Save_OnFail" });
