 */
scwin.trs_Save_OnSuccess = async function() {
    try {
        let msg = $c.stf.getMessageParam("MSG-A001", scwin.LastJob);
        await $c.win.alert(msg);

        // setObjectValue(txb_isur_cd, "");
        // setObjectValue(txb_com_abbrv, "");

        // dts_single.ClearData();
        // dts_FileList.ClearData();
        // dts_single.AddRow();
        // dts_FileList.AddRow();
        $c.frame.path("../").fn_Search();
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF37409.trs_Save_OnSuccess" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadCompleted
 * @description dts_List 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List_OnLoadCompleted = async function(rowcount) {
    try {
        if (dts_List.errorMsg) {
            await $c.win.alert(dts_List.errorMsg);
        } else {
            cmb_YYYY.setValue(dts_List.getCellData(1, "SELCT_BAS_YY"));
            cmb_AW_YYYY.setValue(dts_List.getCellData(1, "EXCNT_DISCLS_CORP_AWARD_YY"));
            txb_isur_cd.setValue(dts_List.getCellData(1, "ISUR_CD"));
            cmb_Excnt.setValue(dts_List.getCellData(1, "EXCNT_DISCLS_CORP_TP_CD"));
            txt_award_prn_nm.setValue(dts_List.getCellData(1, "AWARD_PRN_NM"));
            edt_design_dd.setValue(dts_List.getCellData(1, "DESIGN_DD"));
            cmb_Award.setValue(dts_List.getCellData(1, "VLUP_AWARD_TP_CD"));
            txt_ord.setValue(dts_List.getCellData(1, "VLUP_EXCNT_CORP_ORD"));
            txt_remk.Text = dts_List.getCellData(1, "REMK");

            // setObjectValue(txt_remk, dts_List.NameString(1, "REMK"));

            // 수정을 위한 기존의 선정기준년도 셋팅
            dts_single.setCellData(1, "OLD_SELCT_BAS_YY", dts_List.getCellData(1, "SELCT_BAS_YY"));
            txb_com_abbrv.setValue(gComAbbrv);
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF37409.dts_List_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadError
 * @description dts_List 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
