 */
scwin.trs_delete_OnFail = async function() {
    try {
        await $c.win.alert("삭제" + " 실패");
        await $c.win.alert(trs_delete);
        dts_Delete.Reset();
        dts_Delete.insertRow(); // 성공일 때 Default로 한줄 추가해 놓는다.
