    try {
        const ExcntVal = cmb_Excnt.getValue();
        if (ExcntVal === '99') {
            // 밸류업 우수기업 유형 선택시
            pnl_valueup.show("");
            lbl_2.show("");
        } else {
            pnl_valueup.hide();
            lbl_2.hide();
