/**
 * @method
 * @name setDisplayPanal
 * @description 등록 패널 변경
 * @param {*} rdo_creatloc_tp rdo_creatloc_tp
 * @returns {void}
 * @hidden N
 */
scwin.setDisplayPanal = function(rdo_creatloc_tp) {
    if (scwin.gRdoCreatLoc_tp === "01") {
        // 단건
        panel_2.style.visibility = "";
        panel_3.style.visibility = "hidden";
    } else {
        // 엑셀
        panel_2.style.visibility = "hidden";
        panel_3.style.visibility = "";
    }
};

/**
 * @method
 * @name save
 * @description save 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save = async function() {
    const txb_isur_cd_value = txb_isur_cd.getValue();
    const cmb_YYYY_value = cmb_YYYY.getValue();
    const cmb_AW_YYYY_value = cmb_AW_YYYY.getValue();
    const cmb_Excnt_value = cmb_Excnt.getValue();
    const txt_award_prn_nm_value = txt_award_prn_nm.getValue();
    const edt_design_dd_value = edt_design_dd.getValue();
    const txt_remk_value = txt_remk.Text;
    let cmb_Award_value = "";
    let txt_ord_value = "";
    if (cmb_Excnt_value === '99') {
        cmb_Award_value = cmb_Award.getValue();
        txt_ord_value = txt_ord.getValue();
    }
    if (!await scwin.dateCheck(cmb_YYYY_value, $c.ut.trim(cmb_AW_YYYY_value))) {
        return;
    }
    if (!await scwin.validCheck(params)) {
        return;
    }
    if (params === "update") {
        let res = window.confirm("[변경]하시겠습니까?");
        if (res) {
            dts_single.setCellData(1, "ISUR_CD", txb_isur_cd_value);
            dts_single.setCellData(1, "SELCT_BAS_YY", cmb_YYYY_value);
            dts_single.setCellData(1, "EXCNT_DISCLS_CORP_AWARD_YY", cmb_AW_YYYY_value);
            dts_single.setCellData(1, "EXCNT_DISCLS_CORP_TP_CD", cmb_Excnt_value);
            dts_single.setCellData(1, "REG_ID", js_id);
            dts_single.setCellData(1, "AWARD_PRN_NM", txt_award_prn_nm_value);
            dts_single.setCellData(1, "DESIGN_DD", edt_design_dd_value);
            dts_single.setCellData(1, "REMK", txt_remk_value);
            dts_single.setCellData(1, "VLUP_AWARD_TP_CD", cmb_Award_value);
            dts_single.setCellData(1, "VLUP_EXCNT_CORP_ORD", txt_ord_value);
            scwin.LastJob = "변경 ";
            trs_Save.Action = "/ByPass.do?method=updateExcellentDisclsCorp" + "&SCREN_ID=" + "ULDSTF37409.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_03;
            trs_Save.KeyName = "toinb_dataid4";
            trs_Save.KeyValue = "JSP(I:pInputMaster=dts_single)";
            trs_Save.post();
        }
    } else {
        let res = window.confirm("[저장]하시겠습니까?");
        if (res) {
            if (scwin.gRdoCreatLoc_tp === "01") {
                // 단건 등록

                // if (trim(cmb_AW_YYYY_value) == "") {
                //    msg = getMessageParam("MSG-A005", "시상년도");
                //    alert(msg);cmb_AW_YYYY.focus();return;
                // }

                dts_single.setCellData(1, "ISUR_CD", txb_isur_cd_value);
                dts_single.setCellData(1, "SELCT_BAS_YY", cmb_YYYY_value);
                dts_single.setCellData(1, "EXCNT_DISCLS_CORP_AWARD_YY", cmb_AW_YYYY_value);
                dts_single.setCellData(1, "EXCNT_DISCLS_CORP_TP_CD", cmb_Excnt_value);
                dts_single.setCellData(1, "REG_ID", js_id);
                dts_single.setCellData(1, "AWARD_PRN_NM", txt_award_prn_nm_value);
                dts_single.setCellData(1, "DESIGN_DD", edt_design_dd_value);
                dts_single.setCellData(1, "REMK", txt_remk_value);
                dts_single.setCellData(1, "VLUP_AWARD_TP_CD", cmb_Award_value);
                dts_single.setCellData(1, "VLUP_EXCNT_CORP_ORD", txt_ord_value);
                scwin.LastJob = "저장";
                trs_Save.Action = "/ByPass.do?method=registerExcellentDisclsCorpS" + "&SCREN_ID=" + "ULDSTF37409.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
                trs_Save.KeyName = "toinb_dataid4";
                trs_Save.KeyValue = "JSP(I:pInputMaster=dts_single)";
                trs_Save.post();
            } else {
                // 엑셀 등록
                const file_nm = txb_ATTACH_FILE_NM.getValue();
                if (file_nm === "") {
                    msg = $c.stf.getMessageParam("MSG-A005", "파일업로드");
                    await $c.win.alert(msg);
                    txb_ATTACH_FILE_NM.focus();
                    return;
                }
                scwin.LastJob = "엑셀저장";
                trs_Save.Action = "/ByPass.do?method=registerExcellentDisclsCorpE" + "&SCREN_ID=" + "ULDSTF37409.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
                trs_Save.KeyName = "toinb_dataid4";
                trs_Save.KeyValue = "JSP(I:pInputMaster=dts_single,I:pFile=dts_FileList)";
                trs_Save.post();
            }
        }
    }
};

/**
 * @method
 * @name validCheck
 * @description 신규, 업데이트시 validation 체크 함수
 * @param {*} params params
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.validCheck = async function(params) {
    if (params === "update") {
        // 변경시 체크

    } else {
        // 신규시 체크
        if (txb_isur_cd.getValue() === "") {
            msg = $c.stf.getMessageParam("MSG-A005", "회사코드(명)");
            await $c.win.alert(msg);
            txb_isur_cd.focus();
            return false;
        }
        if (cmb_YYYY.getValue() === "") {
            msg = $c.stf.getMessageParam("MSG-A005", "선정기준년도");
            await $c.win.alert(msg);
            cmb_YYYY.focus();
            return false;
        }
    }

    // 밸류업 우수기업 일때 수상자는 체크하지 않는다. 20250718
    if (txt_award_prn_nm.getValue() === "") {
        if (cmb_Excnt.getValue() !== "99") {
            msg = $c.stf.getMessageParam("MSG-A005", "수상자");
            await $c.win.alert(msg);
            txt_award_prn_nm.focus();
            return false;
        }
    }
    if (txt_ord.getValue() !== "") {
        if (!$c.ut.isNum(txt_ord.getValue())) {
            await $c.win.alert("표시순서는 숫자만 입력하십시오");
            txt_ord.focus();
            return false;
        }
        if (txt_ord.getValue().length > 3) {
            await $c.win.alert("표시순서는 3자리 이하로 입력하십시오");
            txt_ord.focus();
            return false;
        }
    }
    let taSize = 10;
    let overLenTa = ($c.stf.getStringSize(txt_award_prn_nm.getValue()) - taSize);
    if (overLenTa > 0) {
        await $c.win.alert("[ 수상자 ] 항목의 최대입력은 [ " + taSize + " ] byte 입니다.    \n\n[ " + overLenTa + " ] byte 를 초과하였습니다.\n\n확인하세요. ( 한글 : 2 byte  숫자,영문 : 1 byte )");
        txt_award_prn_nm.focus();
        return false;
    }

    // 일자 체크
    if (edt_design_dd.getValue() === "") {
        msg = $c.stf.getMessageParam("MSG-A005", "지정일자");
        await $c.win.alert(msg);
        edt_design_dd.focus();
        return false;
    }
    if (edt_design_dd.getValue().length < 8) {
        await $c.win.alert("지정일자를 올바르게 입력하십시오.");
        edt_design_dd.focus();
        return false;
    }
    taSize = 2000;
    // 비고_TxtArea일때의 길이체크
    overLenTa = ($c.stf.getStringSize(txt_remk.Text) - taSize);
    if (overLenTa > 0) {
        await $c.win.alert("[ 비고 ] 항목의 최대입력은 [ " + taSize + " ] byte 입니다.    \n\n[ " + overLenTa + " ] byte 를 초과하였습니다.\n\n확인하세요. ( 한글 : 2 byte  숫자,영문 : 1 byte )");
        txt_remk.focus();
        return false;
    }
    return true;
};

/**
 * @method
 * @name selectAttach
 * @description 파일선택
 * @returns {void}
 * @hidden N
 */
scwin.selectAttach = function() {
    if (file.getValue() === "") return;
    txb_ATTACH_FILE_NM.setValue(file.getValue());
    dts_FileList.setCellData(1, "fileInfo", file.getValue());
    dts_FileList.setCellData(1, "fileUrl", file.getValue());
};

/**
 * @method
 * @name dateCheck
 * @description date Check 처리
 * @param {*} vSelct_bas_yy vSelct_bas_yy
 * @param {*} vExcnt_discls_corp_award_yy vExcnt_discls_corp_award_yy
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dateCheck = async function(vSelct_bas_yy, vExcnt_discls_corp_award_yy) {
    if (vExcnt_discls_corp_award_yy !== "") {
        if (Number(vSelct_bas_yy) > Number(vExcnt_discls_corp_award_yy)) {
            await $c.win.alert("'시상년도'는 '선정기준년도'이후여야 합니다.");
            cmb_AW_YYYY.setValue(vSelct_bas_yy);
            cmb_AW_YYYY.focus();
            return false;
        }
    }
    return true;
};
